import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.DYd_c05j.js";const u=JSON.parse('{"title":"Product Tour","description":"","frontmatter":{},"headers":[],"relativePath":"product-tour.md","filePath":"product-tour.md","lastUpdated":null}'),n={name:"product-tour.md"};function i(s,e,d,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="product-tour" tabindex="-1">Product Tour <a class="header-anchor" href="#product-tour" aria-label="Permalink to &quot;Product Tour&quot;">​</a></h1><p>Homelab Console turns infrastructure observations into a workflow a human can inspect and control. The operator console is a framework-free TypeScript/Vite application with a minimal <strong>Quiet Operations</strong> interface. It is organized as a ledger, not a card-heavy monitoring dashboard.</p><h2 id="start-in-inbox" tabindex="-1">Start in Inbox <a class="header-anchor" href="#start-in-inbox" aria-label="Permalink to &quot;Start in Inbox&quot;">​</a></h2><p><strong>Inbox</strong> is the default section. Its status rail summarizes healthy systems, critical incidents, tasks needing attention and pending approvals. The list contains only open operational work and links directly to canonical records.</p><p>The console polls bounded read endpoints while visible, pauses background work when the browser tab is hidden and resumes on focus. Sidebar badges expose attention counts without turning every section into a dashboard.</p><h2 id="inspect-the-affected-system" tabindex="-1">Inspect the affected system <a class="header-anchor" href="#inspect-the-affected-system" aria-label="Permalink to &quot;Inspect the affected system&quot;">​</a></h2><p><strong>Systems</strong> lists configured providers and their normalized health states. A provider detail contains:</p><ul><li>summary status, timestamps, driver, transport and watchers;</li><li>governed read/write capabilities from the tool registry;</li><li>normalized capability observations;</li><li>a direct investigation-task action for unhealthy providers.</li></ul><p><strong>Topology</strong> complements Systems with declared physical relationships and a failure-impact view. Neither section scans arbitrary hosts or exposes raw provider responses.</p><h2 id="work-an-incident" tabindex="-1">Work an incident <a class="header-anchor" href="#work-an-incident" aria-label="Permalink to &quot;Work an incident&quot;">​</a></h2><p><strong>Incidents</strong> is separate from watcher configuration. It shows severity, provider, watcher, recurrence, first/last observation and the linked task. An operator can mark an incident already handled only with an explicit note.</p><p><strong>Watchers</strong> owns schedules, thresholds, investigation mode, manual execution and the recent run ledger. This separation keeps detection configuration apart from incident response.</p><h2 id="preserve-evidence-in-a-task" tabindex="-1">Preserve evidence in a task <a class="header-anchor" href="#preserve-evidence-in-a-task" aria-label="Permalink to &quot;Preserve evidence in a task&quot;">​</a></h2><p><strong>Tasks</strong> is the durable handoff boundary between operators, interactive MCP clients and remediation workers. A task carries ownership, findings, checks, invocation evidence, lifecycle history and bounded root-cause context.</p><p>Task mutations use backend-validated transitions and generation/version checks. The interface never treats local UI state as proof that a mutation succeeded.</p><h2 id="run-a-governed-tool" tabindex="-1">Run a governed tool <a class="header-anchor" href="#run-a-governed-tool" aria-label="Permalink to &quot;Run a governed tool&quot;">​</a></h2><p><strong>Tools</strong> exposes the declared catalog with provider, mode, risk and availability filters. Inputs are generated from each tool&#39;s JSON Schema and converted through the same typed frontend helpers used by tests.</p><p>Read tools execute through the shared core. Write or high-risk tools stop at the single-use approval boundary; the browser requests approval, polls its state and executes only after receiving an approved id bound to the exact input.</p><h2 id="keep-the-human-in-charge" tabindex="-1">Keep the human in charge <a class="header-anchor" href="#keep-the-human-in-charge" aria-label="Permalink to &quot;Keep the human in charge&quot;">​</a></h2><p><strong>Approvals</strong> shows waiting and historical requests with live expiry countdowns. Approve requires an explicit confirmation; deny is immediate. The same backend decision path is used by Telegram inline buttons.</p><p><strong>MCP Clients</strong> manages Telegram pairing, per-client identity, token rotation and revocation. Newly issued or rotated bearer tokens are shown once. Conversion to the privileged <code>task-worker.v1</code> capability requires a dedicated confirmation.</p><h2 id="inspect-delivery-and-attribution" tabindex="-1">Inspect delivery and attribution <a class="header-anchor" href="#inspect-delivery-and-attribution" aria-label="Permalink to &quot;Inspect delivery and attribution&quot;">​</a></h2><p><strong>Metrics</strong> separates technical reliability, reviewed routing accuracy, review coverage, metering and attributed cost. <strong>AI Delivery</strong> presents normalized conversation-route outcomes independently from Task Router quality.</p><p><strong>Activity</strong> is the append-only, redacted audit trail. REST, Telegram, watchers and MCP clients converge on the same actor/source model and link events back to tools and tasks.</p><h2 id="what-this-workflow-demonstrates" tabindex="-1">What this workflow demonstrates <a class="header-anchor" href="#what-this-workflow-demonstrates" aria-label="Permalink to &quot;What this workflow demonstrates&quot;">​</a></h2><ol><li>A watcher records a bounded observation and opens an incident.</li><li>Inbox surfaces the incident without becoming a second monitoring system.</li><li>The incident links to persistent task evidence and explicit ownership.</li><li>Tools collect normalized evidence through the shared execution core.</li><li>An infrastructure write waits for one exact operator approval.</li><li>Task, approval and execution events remain attributable in Activity.</li></ol><p>Continue with <a href="./architecture">Architecture</a> for the five-plane model or <a href="./security">Security</a> for the trust boundaries behind this workflow.</p>',27)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
